// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import org.eclipse.rdf4j.common.annotation.Experimental;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics.FilterPassEstimate;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PatternKey;

/**
 * Learns how selective each FILTER actually is, from the rows the engine has already pushed through it.
 * <p>
 * <b>Why this exists.</b> The engine has always measured filter selectivity — {@code RecordingNativeBooleanFilter}
 * counts passed and rejected rows and reports them to {@code LmdbEvaluationStatistics.recordFilterOutcome} when its
 * cursor closes. Until now that sink discarded everything, because the only store behind it was constructed inside the
 * sketch-based join estimator's lifecycle and that estimator is off by default. So the measurement happened on every
 * query and was thrown away. This class terminates that wire with no dependency on the sketch estimator.
 * <p>
 * <b>What it changes.</b> Without it, a filter's planning pass ratio is 1.0 with confidence 0 — "assume everything
 * survives, and do not trust that". Every cost estimate downstream of a FILTER is therefore an over-estimate of the
 * rows, by exactly the factor the filter removes. With it, a filter that has been observed rejecting 95% of its input
 * says so.
 * <p>
 * <b>Three tiers, most specific first.</b> A filter is identified by its own key; failing that by its <em>template</em>
 * (the same expression shape with constants abstracted, so {@code ?x > 5} informs {@code ?x > 7}); failing that by the
 * pattern it sits on. Keys come from {@code FilterSelectivityKeys}, which is shared, sketch-free infrastructure.
 * <p>
 * <b>Confidence is not this class's job.</b> It reports a ratio and the number of observations behind it;
 * {@link FilterPassEstimate} derives a Wilson 95% interval from the evidence count. Two observations produce a ratio
 * with an interval so wide it decides nothing, which is the correct behaviour and needs no threshold here — the small
 * {@link #MIN_EVIDENCE} floor only avoids reporting a "learned" estimate from a literal handful of rows.
 * <p>
 * In memory and per store; nothing is persisted. Bounded so a workload with unbounded filter variety cannot grow it
 * without limit.
 */
@Experimental
final class LmdbLearnedFilterSelectivity {

	/**
	 * Kill switch. This is not inert wiring: {@code estimateFilterPass} feeds
	 * {@code LmdbEvaluationStatistics.meet(Filter)}, which is part of {@code getCardinality}, which the standard
	 * optimizer pipeline uses to order joins. Turning learned selectivity on therefore changes join ordering across
	 * every query containing a FILTER — for the better in principle, since the alternative is assuming filters remove
	 * nothing, but it is a broad change and must be bisectable.
	 */
	static final String ENABLED_PROPERTY = "rdf4j.lmdb.learnedFilterSelectivity.enabled";

	/** Per tier. A workload with more distinct filters than this stops learning new ones rather than growing. */
	private static final int MAX_ENTRIES_PER_TIER = 4096;

	/**
	 * Below this many observed rows a tier is skipped in favour of a broader one. The Wilson interval already widens
	 * with thin evidence, so this is only a floor against reporting a ratio derived from a handful of rows as though it
	 * were learned.
	 */
	private static final long MIN_EVIDENCE = 16L;

	private final Map<String, Outcome> byFilter = new ConcurrentHashMap<>();
	private final Map<String, Outcome> byTemplate = new ConcurrentHashMap<>();
	private final Map<PatternKey, Outcome> byPattern = new ConcurrentHashMap<>();

	static boolean enabled() {
		return !"false".equalsIgnoreCase(System.getProperty(ENABLED_PROPERTY));
	}

	/** Rows a filter saw, split by whether they survived it. */
	private record Outcome(long passed, long filtered) {

		Outcome plus(long morePassed, long moreFiltered) {
			return new Outcome(saturate(passed, morePassed), saturate(filtered, moreFiltered));
		}

		long total() {
			return saturate(passed, filtered);
		}

		double ratio() {
			long total = total();
			return total <= 0L ? -1.0d : (double) passed / (double) total;
		}

		private static long saturate(long left, long right) {
			long sum = left + right;
			return sum < 0L ? Long.MAX_VALUE : sum;
		}
	}

	/**
	 * Records one filter's observed outcome. Signature mirrors the sketch-backed store this replaces so the call site
	 * stays a single line.
	 *
	 * @param unqualified true when the filter's key is not qualified by locally bound components; only then may the
	 *                    observation be folded into the pattern-wide tier, because otherwise that tier would average
	 *                    over genuinely different bound shapes.
	 */
	void recordFilterOutcome(PatternKey key, String filterKey, String filterTemplateKey, long passedCount,
			long filteredCount, boolean unqualified) {
		if (!enabled() || passedCount < 0L || filteredCount < 0L || (passedCount == 0L && filteredCount == 0L)) {
			return;
		}
		accumulate(byFilter, filterKey, passedCount, filteredCount);
		accumulate(byTemplate, filterTemplateKey, passedCount, filteredCount);
		if (unqualified) {
			accumulate(byPattern, key, passedCount, filteredCount);
		}
	}

	private static <K> void accumulate(Map<K, Outcome> tier, K key, long passed, long filtered) {
		if (key == null) {
			return;
		}
		// Bounded: once full, keep refining what is already known rather than admitting new keys.
		if (!tier.containsKey(key) && tier.size() >= MAX_ENTRIES_PER_TIER) {
			return;
		}
		tier.merge(key, new Outcome(passed, filtered), (existing, added) -> existing.plus(added.passed(),
				added.filtered()));
	}

	/**
	 * The most specific learned estimate available, or null when nothing has been observed. A null return leaves the
	 * caller on its existing fallback, which reports "passes everything, confidence zero".
	 */
	FilterPassEstimate estimate(PatternKey key, String filterKey, String filterTemplateKey) {
		if (!enabled()) {
			return null;
		}
		FilterPassEstimate estimate = lookup(byFilter, filterKey, FilterPassEstimate.Source.LEARNED_FILTER);
		if (estimate != null) {
			return estimate;
		}
		estimate = lookup(byTemplate, filterTemplateKey, FilterPassEstimate.Source.LEARNED_TEMPLATE);
		if (estimate != null) {
			return estimate;
		}
		return lookup(byPattern, key, FilterPassEstimate.Source.LEARNED_PATTERN);
	}

	private static <K> FilterPassEstimate lookup(Map<K, Outcome> tier, K key, FilterPassEstimate.Source source) {
		if (key == null) {
			return null;
		}
		Outcome outcome = tier.get(key);
		if (outcome == null || outcome.total() < MIN_EVIDENCE) {
			return null;
		}
		double ratio = outcome.ratio();
		return ratio < 0.0d ? null : new FilterPassEstimate(ratio, source, outcome.total());
	}

	/** Observations retained, per tier. Test and telemetry hook. */
	int size() {
		return byFilter.size() + byTemplate.size() + byPattern.size();
	}

	void clear() {
		byFilter.clear();
		byTemplate.clear();
		byPattern.clear();
	}
}
